#!/usr/bin/env bash
set -euo pipefail
DEST="${ECC_DEST:-$HOME/vhdl_repo/IP_Cores/ECC_Scrubber}"
mkdir -p "$DEST"
echo ">> destino: $DEST"
echo "" | base64 -d > "$DEST/mmio_oracle.py"
echo "" | base64 -d > "$DEST/gen_layer3_trace.py"
echo "" | base64 -d > "$DEST/ecc_regbank.vhd"
echo "" | base64 -d > "$DEST/tb_layer3.vhd"
echo "" | base64 -d > "$DEST/scrub_fsm.vhd"
echo "" | base64 -d > "$DEST/tb_layer2.vhd"
echo ">> generando traza Layer 3 (+ layer3_init.txt)"
( cd "$DEST" && python3 gen_layer3_trace.py )
echo ">> Layer 2 (regresion tras unificar convencion de flags)"
( cd "$DEST" && python3 gen_layer2_vectors.py >/dev/null && rm -rf work-obj08.cf && \
  ghdl -a --std=08 ecc_pkg.vhd ecc_codec.vhd scrub_bram.vhd scrub_fsm.vhd tb_layer2.vhd 2>/dev/null && \
  ghdl -r --std=08 tb_layer2 --stop-time=50us 2>&1 | grep -E "SCRUB (PASS|FAIL)" )
echo ">> Layer 3"
( cd "$DEST" && rm -rf work-obj08.cf && \
  ghdl -a --std=08 ecc_pkg.vhd ecc_codec.vhd scrub_bram.vhd scrub_fsm.vhd ecc_regbank.vhd tb_layer3.vhd 2>/dev/null && \
  ghdl -r --std=08 tb_layer3 --stop-time=100us 2>&1 | grep -E "MMIO (PASS|FAIL)|lecturas|discrepancias" )
echo ">> archivos:"
ls -l "$DEST"/ecc_regbank.vhd "$DEST"/tb_layer3.vhd "$DEST"/mmio_oracle.py "$DEST"/gen_layer3_trace.py
